let render (generation : Migrations_command.generation) ~generated_file =
  
  let quote raw =
    "\""
    ^ ExtString.String.replace_chars
        (function
          | '"' -> "\\\""
          | '\\' -> "\\\\"
          | '\n' -> "\\n"
          | '%' -> "\\%"
          | character -> String.make 1 character)
        raw
    ^ "\""
  in
  let quoted values = String.concat " " (List.map quote values) in
  let committed_log = generation.migrations_file in
  
  let next_log = committed_log ^ ".next" in
  String.concat "\n"
    [
      "; Generated by `sqlgg migrations dune`.";
      "(rule";
      " (targets " ^ quoted [ generated_file; next_log ] ^ ")";
      " (deps "
      ^ quoted
          (generation.schema_file
           :: committed_log
           :: Stdlib.Option.to_list generation.manual_file)
      ^ ")";
      " (action";
      "  (progn";
      "   (with-stdout-to " ^ quote next_log;
      "    (cat " ^ quote committed_log ^ "))";
      "   (with-stdout-to " ^ quote generated_file;
      "    (run %{bin:sqlgg} "
      ^ quoted
          (Migrations_command.generate_arguments
             { generation with migrations_file = next_log })
      ^ ")))))";
      "";
      "(rule";
      " (alias sqlgg-migrations)";
      " (action";
      "  (diff " ^ quoted [ committed_log; next_log ] ^ ")))";
      "";
      "(alias";
      " (name check)";
      " (deps";
      "  (alias sqlgg-migrations)))";
      "";
    ]
